import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Bedingte Sichtbarkeit","description":"Blöcke abhängig von eingegebenen Werten ein- und ausblenden.","frontmatter":{"title":"Bedingte Sichtbarkeit","description":"Blöcke abhängig von eingegebenen Werten ein- und ausblenden."},"headers":[],"relativePath":"seiten/sichtbarkeit.md","filePath":"seiten/sichtbarkeit.md","lastUpdated":1786434193000}'),a={name:"seiten/sichtbarkeit.md"};function s(l,e,d,c,o,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="bedingte-sichtbarkeit" tabindex="-1">Bedingte Sichtbarkeit <a class="header-anchor" href="#bedingte-sichtbarkeit" aria-label="Permalink to &quot;Bedingte Sichtbarkeit&quot;">​</a></h1><p>Blöcke lassen sich abhängig von den Werten anderer Felder ein- und ausblenden. Damit wird aus einer statischen Seite ein Formular, das auf Eingaben reagiert.</p><div class="warning custom-block"><p class="custom-block-title">Nur im höchsten Tarif</p><blockquote><p><em>Upgraden Sie auf Pro, um Blöcke basierend auf Formularfeldwerten ein- oder auszublenden.</em></p></blockquote></div><h2 id="bedingung-anlegen" tabindex="-1">Bedingung anlegen <a class="header-anchor" href="#bedingung-anlegen" aria-label="Permalink to &quot;Bedingung anlegen&quot;">​</a></h2><ol><li>Wählen Sie den Block aus, der bedingt erscheinen soll.</li><li>Öffnen Sie in den Blockeinstellungen den Bereich <strong>Sichtbarkeit</strong>.</li><li>Wählen Sie <strong>Feld</strong>, <strong>Bedingung</strong> und <strong>Wert</strong>.</li></ol><p>Über <strong>Entfernen</strong> löschen Sie die Bedingung wieder.</p><h2 id="verfugbare-bedingungen" tabindex="-1">Verfügbare Bedingungen <a class="header-anchor" href="#verfugbare-bedingungen" aria-label="Permalink to &quot;Verfügbare Bedingungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bedingung</th><th>Sinnvoll bei</th></tr></thead><tbody><tr><td><strong>ist leer</strong> / <strong>ist nicht leer</strong></td><td>allen Feldtypen</td></tr><tr><td><strong>ist wahr</strong> / <strong>ist falsch</strong></td><td>Häkchen, Entscheidung</td></tr><tr><td><strong>ist gleich</strong> / <strong>ist nicht gleich</strong></td><td>Auswahl, Text, Zahlen</td></tr><tr><td><strong>ist größer als</strong> / <strong>ist kleiner als</strong></td><td>Zahlen, Datum</td></tr></tbody></table><h2 id="ruckmeldung-im-editor" tabindex="-1">Rückmeldung im Editor <a class="header-anchor" href="#ruckmeldung-im-editor" aria-label="Permalink to &quot;Rückmeldung im Editor&quot;">​</a></h2><p>Der Editor zeigt an, was gilt:</p><ul><li><em>Sichtbar wenn {Bedingung}</em> — die eingestellte Regel</li><li><strong>Aktuell sichtbar</strong> beziehungsweise <strong>Aktuell ausgeblendet</strong> — der Zustand mit den gerade eingetragenen Werten</li></ul><div class="tip custom-block"><p class="custom-block-title">Im Editor durchspielen</p><p>Tragen Sie im Editor testweise Werte ein und beobachten Sie, wie die Anzeige zwischen <em>Aktuell sichtbar</em> und <em>Aktuell ausgeblendet</em> wechselt. So prüfen Sie die Bedingung, ohne die Seite zu veröffentlichen.</p></div><h2 id="erweitert-apptivescript" tabindex="-1">Erweitert: ApptiveScript <a class="header-anchor" href="#erweitert-apptivescript" aria-label="Permalink to &quot;Erweitert: ApptiveScript&quot;">​</a></h2><p>Für Fälle, die die einfache Auswahl nicht abdeckt, gibt es <strong>Erweitert (ApptiveScript)</strong>. Der Platzhalter zeigt die Schreibweise:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(18)</span></span></code></pre></div><p>Der Zugriff erfolgt über den <strong>Key</strong> des Feldes — nicht über seine Beschriftung.</p><div class="warning custom-block"><p class="custom-block-title">Keys vorher festlegen</p><p>Ändern Sie den Key eines Eingabeblocks, greifen bestehende Bedingungen ins Leere — ohne Fehlermeldung. Legen Sie sprechende Keys fest, <strong>bevor</strong> Sie damit arbeiten.</p><p>Über <strong>Keys verwalten</strong> sehen Sie alle Keys einer Seite. → <a href="/seiten/eingabebloecke">Eingabeblöcke</a></p></div><p>Für die gängigen Fälle reicht die einfache Auswahl aus Feld, Bedingung und Wert. Darüber hinaus: <a href="/apptivescript/schreibweise">Schreibweise</a>, <a href="/apptivescript/werte-referenzieren">Werte referenzieren</a> und die <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a>. Die Bedingung muss am Ende einen Wahrheitswert ergeben.</p><div class="warning custom-block"><p class="custom-block-title">Zwei Fehlerbilder, zwei Ursachen</p><p>Ein Block, der <strong>nie</strong> erscheint, deutet auf einen falschen Key — die Bedingung ist dann immer falsch. Ein Block, der <strong>immer</strong> erscheint, deutet auf einen Schreibfehler im Ausdruck: Bei einem fehlerhaften Ausdruck bleibt der Block sichtbar.</p></div><h2 id="typische-anwendungen" tabindex="-1">Typische Anwendungen <a class="header-anchor" href="#typische-anwendungen" aria-label="Permalink to &quot;Typische Anwendungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Bedingung</th></tr></thead><tbody><tr><td>Rückfrage nur bei Ablehnung</td><td><code>Entscheidung</code> <em>ist falsch</em></td></tr><tr><td>Zusatzfelder nur bei „Sonstiges&quot;</td><td><code>Kategorie</code> <em>ist gleich</em> <code>Sonstiges</code></td></tr><tr><td>Erwachsenenbereich</td><td><code>Alter</code> <em>ist größer als</em> <code>17</code></td></tr><tr><td>Nachfrage bei schlechter Bewertung</td><td><code>Bewertung</code> <em>ist kleiner als</em> <code>3</code></td></tr><tr><td>Details nur bei Angabe</td><td><code>Auftragsnummer</code> <em>ist nicht leer</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Kurze Formulare durch bedingte Felder</p><p>Statt allen alles vorzulegen, zeigen Sie zunächst wenige Felder und blenden Zusätzliches nur bei Bedarf ein. Das senkt die Abbruchquote deutlich — besonders auf Mobilgeräten.</p><p>Das ist zugleich der Hauptgrund, eine <a href="/seiten/was-sind-seiten">Seite</a> statt eines <a href="/formulare/formular-erstellen">Formulars</a> zu bauen: Formulare kennen keine bedingte Anzeige.</p></div><h2 id="ganze-bereiche-ein-und-ausblenden" tabindex="-1">Ganze Bereiche ein- und ausblenden <a class="header-anchor" href="#ganze-bereiche-ein-und-ausblenden" aria-label="Permalink to &quot;Ganze Bereiche ein- und ausblenden&quot;">​</a></h2><p>Die Sichtbarkeit wirkt auf <strong>einen Block</strong>. Setzen Sie sie auf ein <a href="/seiten/layout-bloecke">Layout</a>, verschwindet dessen gesamter Inhalt mit.</p><div class="tip custom-block"><p class="custom-block-title">Layout als Container nutzen</p><p>Sollen fünf Felder gemeinsam erscheinen, packen Sie sie in ein vertikales Layout und setzen die Bedingung <strong>einmal</strong> darauf — statt fünfmal einzeln. Das ist übersichtlicher und leichter zu ändern.</p></div><h2 id="grenzen" tabindex="-1">Grenzen <a class="header-anchor" href="#grenzen" aria-label="Permalink to &quot;Grenzen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Was die Sichtbarkeit nicht leistet</p><ul><li><strong>Kein Zugriffsschutz.</strong> Ein ausgeblendeter Block ist nicht geschützt, nur unsichtbar. Für echte Beschränkungen dienen <a href="/zusammenarbeit/zugriff-beschraenken">Zugriffsbeschränkungen</a>.</li><li><strong>Nicht innerhalb von HTML-Blöcken.</strong> Die Bedingung wirkt auf den <a href="/seiten/html-bloecke">HTML-Block</a> als Ganzes, nicht auf Teile darin.</li><li><strong>Nur eine Bedingung je Block</strong> über die einfache Auswahl. Kombinationen brauchen <code>logicalAnd</code> beziehungsweise <code>logicalOr</code> → <a href="/apptivescript/schreibweise">Schreibweise</a>.</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Pflichtfelder in ausgeblendeten Blöcken</p><p>Prüfen Sie, wie sich ein ausgeblendetes Pflichtfeld verhält, bevor Sie die Seite produktiv nehmen. Testen Sie beide Fälle — Bedingung erfüllt und nicht erfüllt — jeweils bis zum Absenden.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/seiten/eingabebloecke">Eingabeblöcke</a></li><li><a href="/seiten/layout-bloecke">Layout-Blöcke</a></li><li><a href="/seiten/seite-erstellen">Seite erstellen und bearbeiten</a></li></ul>',30)])])}const b=n(a,[["render",s]]);export{h as __pageData,b as default};
